/* Direct C# port of EngineFX t4_t6_decode.h and t4_t6_decode_states.h. */

namespace TKFaxEngine.FaxImage;

internal enum t4_decode_state_code_t : byte {
    S_Null = 0,
    S_Pass = 1,
    S_Horiz = 2,
    S_Vert = 3,
    S_Ext = 4,
    S_TermW = 5,
    S_TermB = 6,
    S_MakeUpW = 7,
    S_MakeUpB = 8,
    S_MakeUp = 9,
    S_EOL = 10
}

internal readonly struct t4_table_entry_t {
    internal t4_table_entry_t(t4_decode_state_code_t state, byte width, short param) {
        this.state = state;
        this.width = width;
        this.param = param;
    }

    internal t4_table_entry_t(t4_decode_state_code_t state, int width, int param)
        : this(state, checked((byte)width), checked((short)param)) {
    }

    internal readonly t4_decode_state_code_t state;
    internal readonly byte width;
    internal readonly short param;
}

public sealed class t4_t6_decode_state_t {
    public t4_row_write_handler_t? row_write_handler;
    public object? row_write_user_data;
    public int encoding;
    public int image_width;
    public int image_length;
    public int bytes_per_row;
    public int row_bits;
    public byte[] row_buf = Array.Empty<byte>();
    public bool row_is_2d;
    public int row_len;
    public uint[] cur_runs = Array.Empty<uint>();
    public uint[] ref_runs = Array.Empty<uint>();
    public int consecutive_eols;
    public int a0;
    public int b1;
    public int run_length;
    public int black_white;
    public bool in_black;
    public int a_cursor;
    public int b_cursor;
    public uint rx_bitstream;
    public int rx_bits;
    public int rx_skip_bits;
    public uint pixel_stream;
    public int pixels;
    public int min_row_bits;
    public int max_row_bits;
    public int compressed_image_size;
    public int curr_bad_row_run;
    public int longest_bad_row_run;
    public int bad_rows;
    public SpanLogState logging = new();
}

